import{_ as l,I as s,c as r,o as t,a3 as e,b as o,w as i,a as d,J as h,a4 as g}from"./chunks/framework.BusRvirq.js";const u=JSON.parse('{"title":"LLM 파인튜닝 후 성능 저하 원인 및 해결책 분석","description":"도메인 특화 LLM 파인튜닝 시 발생하는 일반 추론 능력 저하(파국적 망각)의 근본 메커니즘과 LoRA 하이퍼파라미터 최적화 및 정규화 리플레이 기법","frontmatter":{"title":"LLM 파인튜닝 후 성능 저하 원인 및 해결책 분석","shortTitle":"파인튜닝 성능 저하 분석","description":"도메인 특화 LLM 파인튜닝 시 발생하는 일반 추론 능력 저하(파국적 망각)의 근본 메커니즘과 LoRA 하이퍼파라미터 최적화 및 정규화 리플레이 기법","category":"AI 연구","sort":500,"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/study/LLM 파인튜닝 후 성능 저하 원인 및 해결책 분석.html"}]]},"headers":[],"relativePath":"study/LLM 파인튜닝 후 성능 저하 원인 및 해결책 분석.md","filePath":"ko/study/LLM 파인튜닝 후 성능 저하 원인 및 해결책 분석.md","lastUpdated":1789435621000}'),p={name:"study/LLM 파인튜닝 후 성능 저하 원인 및 해결책 분석.md"};function E(_,a,c,k,A,m){const n=s("Mermaid");return t(),r("div",null,[a[1]||(a[1]=e('<h1 id="llm-파인튜닝-후-성능-저하-원인-및-해결책-분석" tabindex="-1">LLM 파인튜닝 후 성능 저하 원인 및 해결책 분석 <a class="header-anchor" href="#llm-파인튜닝-후-성능-저하-원인-및-해결책-분석" aria-label="Permalink to “LLM 파인튜닝 후 성능 저하 원인 및 해결책 분석”">​</a></h1><h2 id="_1-개요-및-문제-정의" tabindex="-1">1. 개요 및 문제 정의 <a class="header-anchor" href="#_1-개요-및-문제-정의" aria-label="Permalink to “1. 개요 및 문제 정의”">​</a></h2><p>도메인 특화 작업(예: SQL 생성, 사내 규정 QA, 의료/금융 분석)을 위해 파운데이션 모델(Foundation Model)을 파인튜닝(Fine-tuning)할 때, 목표 태스크의 정확도는 향상되지만 <strong>일반 추론(General Reasoning), 수리적 사고, 다국어 번역, 코딩 능력 등 기초 능력이 급격히 붕괴하는 현상</strong>이 빈번하게 관측됩니다.</p><p>이를 학술적으로 <strong>파국적 망각(Catastrophic Forgetting)</strong> 또는 <strong>정렬 비용(Alignment Tax)</strong>이라 부르며, 엔터프라이즈 AI 시스템 구축 시 반드시 해결해야 할 핵심 과제입니다.</p><hr><h2 id="_2-성능-저하의-4대-핵심-원인" tabindex="-1">2. 성능 저하의 4대 핵심 원인 <a class="header-anchor" href="#_2-성능-저하의-4대-핵심-원인" aria-label="Permalink to “2. 성능 저하의 4대 핵심 원인”">​</a></h2>',6)),(t(),o(g,null,{default:i(()=>[h(n,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Degradation%5B%ED%8C%8C%EC%9D%B8%ED%8A%9C%EB%8B%9D%20%ED%9B%84%20%EC%84%B1%EB%8A%A5%20%EC%A0%80%ED%95%98%5D%0A%20%20%20%20Degradation%20--%3E%20Cause1%5B1.%20%ED%8C%8C%EA%B5%AD%EC%A0%81%20%EB%A7%9D%EA%B0%81%3Cbr%2F%3E(%EA%B0%80%EC%A4%91%EC%B9%98%20%EA%B3%B5%EA%B0%84%EC%9D%98%20%EA%B8%89%EA%B2%A9%ED%95%9C%20%EC%9D%B4%EB%8F%99)%5D%0A%20%20%20%20Degradation%20--%3E%20Cause2%5B2.%20%EA%B3%BC%EC%A0%81%ED%95%A9%20%EB%B0%8F%20%EB%8B%A4%EC%96%91%EC%84%B1%20%EC%83%81%EC%8B%A4%3Cbr%2F%3E(Overfitting%20to%20Narrow%20Format)%5D%0A%20%20%20%20Degradation%20--%3E%20Cause3%5B3.%20LoRA%20%EB%9E%AD%ED%81%AC%20%EB%B0%8F%20%EC%95%8C%ED%8C%8C%20%EB%B6%88%EA%B7%A0%ED%98%95%3Cbr%2F%3E(Rank%20Saturation%20%26%20Scaling)%5D%0A%20%20%20%20Degradation%20--%3E%20Cause4%5B4.%20%EB%A0%88%EC%9D%B4%EB%B8%94%20%EB%85%B8%EC%9D%B4%EC%A6%88%20%26%20%EB%8D%B0%EC%9D%B4%ED%84%B0%20%EC%98%A4%EC%97%BC%3Cbr%2F%3E(Format%20Inconsistency)%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e(`<h3 id="_2-1-가중치-공간의-급격한-변위-catastrophic-forgetting" tabindex="-1">2.1 가중치 공간의 급격한 변위 (Catastrophic Forgetting) <a class="header-anchor" href="#_2-1-가중치-공간의-급격한-변위-catastrophic-forgetting" aria-label="Permalink to “2.1 가중치 공간의 급격한 변위 (Catastrophic Forgetting)”">​</a></h3><p>파운데이션 모델은 수조 개의 토큰을 사전 학습(Pre-training)하며 광범위한 다차원 매니폴드(Manifold) 상에 균형 잡힌 가중치를 형성합니다.<br> 소규모 도메인 데이터셋으로 전체 가중치를 미세 조정(Full Fine-Tuning)하거나 과도하게 높은 학습률(Learning Rate)을 적용하면, 기존의 최적화 유역(Basin)을 벗어나 특정 태스크에만 편향된 가중치 국소점으로 이동하게 됩니다.</p><h3 id="_2-2-출력-형식-과적합-format-overfitting" tabindex="-1">2.2 출력 형식 과적합 (Format Overfitting) <a class="header-anchor" href="#_2-2-출력-형식-과적합-format-overfitting" aria-label="Permalink to “2.2 출력 형식 과적합 (Format Overfitting)”">​</a></h3><p>특정 JSON 템플릿이나 짧은 문장 형식을 강제 학습시킬 경우, 모델은 문제의 본질적인 인과관계를 추론하는 능력 대신 <strong>표면적인 문법 패턴만을 모방(Surface Pattern Mimicking)</strong>하게 되며, 약간의 프롬프트 변형에도 오답을 출력하는 취약성을 드러냅니다.</p><h3 id="_2-3-lora-low-rank-adaptation-하이퍼파라미터-불일치" tabindex="-1">2.3 LoRA(Low-Rank Adaptation) 하이퍼파라미터 불일치 <a class="header-anchor" href="#_2-3-lora-low-rank-adaptation-하이퍼파라미터-불일치" aria-label="Permalink to “2.3 LoRA(Low-Rank Adaptation) 하이퍼파라미터 불일치”">​</a></h3><p>PEFT(Parameter-Efficient Fine-Tuning) 기법인 LoRA 사용 시, $r$(Rank)과 $\\alpha$(Alpha)의 비율 및 학습률 설정 오류로 인해 가중치 업데이트 크기가 모델 기저 지식을 덮어쓰는 문제가 발생합니다: $$\\Delta W = \\frac{\\alpha}{r} (B \\times A)$$</p><ul><li>$r$이 너무 크면(예: $r=128$) 파운데이션 모델의 일반화 능력을 파괴할 위험이 커집니다.</li><li>$\\alpha / r$ 비율이 2.0을 초과하면 업데이트 크기가 지나치게 커져 이전 지식의 파괴적 소실이 가속됩니다.</li></ul><hr><h2 id="_3-실증적-해결-방안-및-완화-전략" tabindex="-1">3. 실증적 해결 방안 및 완화 전략 <a class="header-anchor" href="#_3-실증적-해결-방안-및-완화-전략" aria-label="Permalink to “3. 실증적 해결 방안 및 완화 전략”">​</a></h2><h3 id="_3-1-일반-도메인-데이터-리플레이-혼합-general-replay-mixing" tabindex="-1">3.1 일반 도메인 데이터 리플레이 혼합 (General Replay Mixing) <a class="header-anchor" href="#_3-1-일반-도메인-데이터-리플레이-혼합-general-replay-mixing" aria-label="Permalink to “3.1 일반 도메인 데이터 리플레이 혼합 (General Replay Mixing)”">​</a></h3><p>가장 효과적인 해결책은 도메인 특화 데이터셋에 <strong>5% ~ 15% 비율의 고품질 일반 추론 데이터셋(General Instruction Replay Dataset)</strong>을 혼합하여 학습하는 것입니다.</p><div class="language-python"><button title="Copy code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 데이터셋 혼합 비율 예시 (PyTorch Dataset)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">domain_samples </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> load_domain_dataset()       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 85% (도메인 특화 데이터)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">general_samples </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> load_alpaca_eval_mix()     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 15% (일반 추론/수학/코딩 정규화 데이터)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">training_dataset </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ConcatDataset([domain_samples, general_samples])</span></span></code></pre></div><ul><li><strong>효과</strong>: 손실 함수(Loss function)가 일반 추론 능력의 그래디언트를 지속적으로 반영하여 가중치가 기존 매니폴드 영역 내에서 안정적으로 유지됩니다.</li></ul><h3 id="_3-2-lora-하이퍼파라미터-골든-룰-golden-rules" tabindex="-1">3.2 LoRA 하이퍼파라미터 골든 룰 (Golden Rules) <a class="header-anchor" href="#_3-2-lora-하이퍼파라미터-골든-룰-golden-rules" aria-label="Permalink to “3.2 LoRA 하이퍼파라미터 골든 룰 (Golden Rules)”">​</a></h3><ol><li><strong>Rank와 Alpha 권장 설정</strong>: <ul><li>$r = 16$ 또는 $r = 32$ (대부분의 다운스트림 태스크에 충분)</li><li>$\\alpha = 16$ 또는 $\\alpha = 32$ ($ rac{\\alpha}{r} = 1.0$)</li></ul></li><li><strong>타깃 모듈 확장</strong>: 오직 <code>q_proj</code>, <code>v_proj</code>만 학습하기보다는 모든 선형 계층(<code>q, k, v, o, gate, up, down</code>)에 저차원 어댑터를 적용하는 것이 파국적 망각을 최소화합니다.</li><li><strong>Weight Decay 및 코사인 스케줄러</strong>: <ul><li>Cosine Annealing Learning Rate Schedule 적용</li><li>Warmup ratio 0.05 ~ 0.1 설정</li></ul></li></ol><h3 id="_3-3-neftune-noisy-embedding-fine-tuning-기법-도입" tabindex="-1">3.3 NEFTune (Noisy Embedding Fine-Tuning) 기법 도입 <a class="header-anchor" href="#_3-3-neftune-noisy-embedding-fine-tuning-기법-도입" aria-label="Permalink to “3.3 NEFTune (Noisy Embedding Fine-Tuning) 기법 도입”">​</a></h3><p>임베딩 레이어에 가우시안 노이즈(Gaussian Noise)를 미세하게 주입하여 모델이 표면적인 토큰 토폴로지에 과적합되는 것을 방지합니다: $$\\tilde{E} = E + \\frac{\\alpha}{\\sqrt{L \\cdot d}} \\cdot \\text{Uniform}(-1, 1)$$</p><ul><li>학습 데이터의 정답 패턴 암기를 억제하고 의미론적 추론 능력을 유지시키는 데 탁월한 효과를 보입니다.</li></ul><hr><h2 id="_4-검증-체크리스트-및-벤치마크-파이프라인" tabindex="-1">4. 검증 체크리스트 및 벤치마크 파이프라인 <a class="header-anchor" href="#_4-검증-체크리스트-및-벤치마크-파이프라인" aria-label="Permalink to “4. 검증 체크리스트 및 벤치마크 파이프라인”">​</a></h2><p>파인튜닝 완료 후 프로덕션 배포 전, 도메인 점수뿐만 아니라 <strong>기초 벤치마크의 회귀 여부를 필수 점검</strong>해야 합니다:</p><table tabindex="0"><thead><tr><th style="text-align:left;">평가 지표</th><th style="text-align:left;">점검 대상</th><th style="text-align:left;">통과 기준 (Threshold)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Domain Benchmark</strong></td><td style="text-align:left;">도메인 특화 정밀도/재현율</td><td style="text-align:left;">베이스 모델 대비 <strong>+15% 이상 향상</strong></td></tr><tr><td style="text-align:left;"><strong>MMLU / ARC</strong></td><td style="text-align:left;">일반 지식 및 상식 추론</td><td style="text-align:left;">베이스 모델 대비 <strong>-3% 이내 방어</strong></td></tr><tr><td style="text-align:left;"><strong>GSM8K</strong></td><td style="text-align:left;">다단계 수리적 연산 능력</td><td style="text-align:left;">베이스 모델 대비 <strong>-5% 이내 방어</strong></td></tr><tr><td style="text-align:left;"><strong>HumanEval</strong></td><td style="text-align:left;">파이썬 코딩 및 문법 생성</td><td style="text-align:left;">베이스 모델 대비 <strong>-5% 이내 방어</strong></td></tr></tbody></table>`,22))])}const B=l(p,[["render",E]]);export{u as __pageData,B as default};
